<script setup>
import { Link, useForm, usePage } from '@inertiajs/vue3'
import { computed } from 'vue'

const props = defineProps({ billing: Object, activeSupportSession: Object, adminSupport: Boolean, supportAdmin: Object, adminSupportSession: Object })
const graceForm = useForm({ until_date: props.billing.grace.min?.slice?.(0, 10) || '', reason: '' })
const purchaseForm = useForm({ package_id: '', months: 1, method: 'bkash', trx_id: '', note: '' })
const logoutForm = useForm({})
const page = usePage()
const support = computed(() => Boolean(props.adminSupport))
const graceUrl = computed(() => support.value ? `/admin/support-sessions/${props.adminSupportSession.id}/subscription/grace` : '/subscription/grace')
const purchaseUrl = computed(() => support.value ? `/admin/support-sessions/${props.adminSupportSession.id}/subscription/purchase` : '/subscription/purchase')
const logoutUrl = computed(() => support.value ? `/admin/support-sessions/${props.adminSupportSession.id}/end` : '/logout')
const portal = computed(() => page.props.currentPortal || props.currentPortal || {})
function logout() { logoutForm.post(logoutUrl.value) }
function buy() { purchaseForm.post(purchaseUrl.value) }
function requestGrace() { graceForm.post(graceUrl.value) }
</script>

<template>
  <main class="main">
    <nav class="navbar navbar-top fixed-top navbar-expand" id="navbarDefault"><div class="container-fluid justify-content-between">
      <a href="/" class="navbar-brand d-flex align-items-center"><img :src="'/media/assets/img/icons/logo.png?size=128'" alt="" width="28"><span class="ms-2 fw-bold">phoenix</span></a>
      <div class="d-flex align-items-center gap-3"><span v-if="support" class="badge badge-phoenix-warning">Support session · {{ supportAdmin?.name }}</span><span class="text-body-secondary">{{ portal.portal_name }}</span><button class="btn btn-sm btn-phoenix-secondary" :disabled="logoutForm.processing" @click="logout">{{ support ? 'End support' : 'Sign out' }}</button></div>
    </div></nav>
    <nav class="navbar navbar-vertical navbar-expand-lg"><div class="navbar-vertical-content"><ul class="navbar-nav flex-column"><li class="nav-item"><p class="navbar-vertical-label">Portal</p><hr class="navbar-vertical-line"><div class="nav-item-wrapper"><Link href="/" class="nav-link label-1 active"><span class="nav-link-icon">⌂</span><span class="nav-link-text">Dashboard</span></Link></div><div class="nav-item-wrapper"><Link href="/categories" class="nav-link label-1"><span class="nav-link-icon">▦</span><span class="nav-link-text">Categories</span></Link></div><div class="nav-item-wrapper"><Link href="/news/create" class="nav-link label-1"><span class="nav-link-icon">✎</span><span class="nav-link-text">News entry</span></Link></div></li></ul></div></nav>
    <div class="content">
      <div v-if="$page.props.flash?.billing_success" class="alert alert-subtle-success">{{ $page.props.flash.billing_success }}</div><div v-if="$page.props.flash?.warning" class="alert alert-subtle-warning">{{ $page.props.flash.warning }}</div>
      <div class="d-flex flex-wrap justify-content-between align-items-center mb-4"><div><h2 class="mb-1">{{ portal.portal_name || 'Portal dashboard' }}</h2><p class="text-body-tertiary mb-0">Manage your portal and subscription</p></div><div v-if="billing.info.subscription" class="text-end"><span class="badge" :class="billing.info.state==='grace'?'badge-phoenix-danger':'badge-phoenix-success'">{{ billing.info.state }}</span><div class="small text-body-tertiary mt-1">{{ billing.info.subscription.package?.name }} · {{ billing.info.days_left }} day(s) left</div></div></div>
      <div v-if="billing.banner.show" class="alert" :class="billing.banner.is_grace?'alert-subtle-danger':'alert-subtle-warning'"><b>{{ billing.banner.message }}</b><span v-if="billing.grace.can_request && !billing.pendingGrace" class="ms-2">You can ask the administrator for a grace period below.</span></div>
      <div class="row g-3 mb-4"><div class="col-md-4"><div class="card h-100"><div class="card-body"><div class="stat-label">Subscription</div><div class="stat-value">{{ billing.info.state }}</div><div v-if="billing.info.subscription" class="text-body-tertiary">Expires {{ billing.info.subscription.ends_at }}</div></div></div></div><div class="col-md-4"><div class="card h-100"><div class="card-body"><div class="stat-label">Portal status</div><div class="stat-value">{{ portal.status || 'active' }}</div></div></div></div><div class="col-md-4"><div class="card h-100"><div class="card-body"><div class="stat-label">Available plans</div><div class="stat-value">{{ billing.packages.length }}</div></div></div></div></div>
      <div class="row g-3"><section class="col-lg-6"><div class="card h-100"><div class="card-header"><h5 class="mb-0">Grace period</h5></div><div class="card-body"><div v-if="billing.pendingGrace" class="alert alert-subtle-warning mb-0">Your request until {{ billing.pendingGrace.until_date }} is waiting for approval.</div><form v-else-if="billing.grace.can_request" @submit.prevent="requestGrace"><label class="form-label" for="until_date">Requested until</label><input id="until_date" v-model="graceForm.until_date" class="form-control mb-2" type="date" :min="String(billing.grace.min).slice(0,10)" :max="String(billing.grace.max).slice(0,10)" required><div v-if="graceForm.errors.until_date" class="text-danger small mb-2">{{ graceForm.errors.until_date }}</div><label class="form-label" for="reason">Reason (optional)</label><textarea id="reason" v-model="graceForm.reason" class="form-control mb-3" maxlength="500" rows="2"></textarea><button class="btn btn-primary" :disabled="graceForm.processing">Request grace period</button></form><p v-else class="text-body-tertiary mb-0">Grace requests open near the end of your subscription.</p></div></div></section>
        <section class="col-lg-6"><div class="card h-100"><div class="card-header"><h5 class="mb-0">Renew subscription</h5></div><div class="card-body"><div v-if="billing.pendingPurchase" class="alert alert-subtle-warning mb-0">Your renewal request for {{ billing.pendingPurchase.package?.name }} is waiting for approval.</div><form v-else @submit.prevent="buy"><label class="form-label" for="plan">Plan</label><select id="plan" v-model="purchaseForm.package_id" class="form-select mb-2" required><option value="">Choose a plan</option><option v-for="p in billing.packages" :key="p.id" :value="p.id">{{ p.name }} · ৳{{ p.price }}/month</option></select><div v-if="purchaseForm.errors.package_id" class="text-danger small mb-2">{{ purchaseForm.errors.package_id }}</div><label class="form-label" for="months">Months</label><input id="months" v-model="purchaseForm.months" class="form-control mb-2" type="number" min="1" max="60" required><label class="form-label" for="method">Payment method</label><select id="method" v-model="purchaseForm.method" class="form-select mb-2"><option v-for="(label,key) in $page.props.billingMethods || {cash:'Cash',bkash:'bKash',nagad:'Nagad',rocket:'Rocket',bank:'Bank'}" :key="key" :value="key">{{ label }}</option></select><label class="form-label" for="trx_id">Transaction ID</label><input id="trx_id" v-model="purchaseForm.trx_id" class="form-control mb-2"><label class="form-label" for="note">Note</label><input id="note" v-model="purchaseForm.note" class="form-control mb-3"><button class="btn btn-primary" :disabled="purchaseForm.processing">Send renewal request</button></form></div></div></section>
      </div>
      <div class="card mt-3"><div class="card-header"><h5 class="mb-0">Available plans</h5></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Package</th><th>Monthly price</th><th>Term</th><th>Months due</th></tr></thead><tbody><tr v-for="p in billing.packages" :key="p.id"><td>{{ p.name }}</td><td>৳{{ p.price }}</td><td>{{ p.term_months }} months</td><td>{{ p.min_months }}–{{ p.max_months }}</td></tr><tr v-if="!billing.packages.length"><td colspan="4" class="text-body-tertiary">No plans are currently available.</td></tr></tbody></table></div></div>
      <div v-if="billing.extras.one_time || billing.extras.cycle" class="text-body-tertiary mt-3">Additional charges: one time ৳{{ billing.extras.one_time }}, per cycle ৳{{ billing.extras.cycle }}.</div>
    </div>
  </main>
</template>
